<?php
declare(strict_types=1);
require __DIR__ . '/db.php';
session_start();
if (empty($_SESSION['user_id'])) jsonResponse(false, 'Потрібна авторизація.', [], 401);
$pdo = db(); $userId = (string)$_SESSION['user_id']; $method = $_SERVER['REQUEST_METHOD'] ?? 'GET'; $data = $method === 'POST' ? body() : []; $action = (string)($data['action'] ?? '');
$userQuery = $pdo->prepare('SELECT id, name, email, role FROM users WHERE id = ? LIMIT 1'); $userQuery->execute([$userId]); $user = $userQuery->fetch();
if (!$user) jsonResponse(false, 'Користувача не знайдено.', [], 401);
$isAdmin = in_array($user['role'], ['admin', 'owner'], true);
$canManage = in_array($user['role'], ['admin', 'owner', 'manager'], true);
function taskAccessSql(array $user, string $userId): array { if (in_array($user['role'], ['admin', 'owner'], true)) return ['', []]; return [' AND (t.created_by = ? OR t.assignee_id = ? OR EXISTS (SELECT 1 FROM task_assignees ta0 WHERE ta0.task_id = t.id AND ta0.user_id = ?))', [$userId, $userId, $userId]]; }
function idList($value): array { $values = is_array($value) ? $value : ($value === null || $value === '' ? [] : [$value]); return array_values(array_unique(array_filter(array_map(static fn($item): string => trim((string)$item), $values)))); }
function taskSelect(string $where = '1=1'): string { return "SELECT t.*, GROUP_CONCAT(DISTINCT tp.project_id) AS project_ids, GROUP_CONCAT(DISTINCT p.name SEPARATOR ', ') AS project_names, GROUP_CONCAT(DISTINCT ta.user_id) AS assignee_ids, GROUP_CONCAT(DISTINCT a.name SEPARATOR ', ') AS assignee_names, p0.name AS primary_project_name, a0.name AS primary_assignee_name, c.name AS creator_name FROM tasks t LEFT JOIN task_projects tp ON tp.task_id = t.id LEFT JOIN projects p ON p.id = tp.project_id LEFT JOIN task_assignees ta ON ta.task_id = t.id LEFT JOIN users a ON a.id = ta.user_id LEFT JOIN projects p0 ON p0.id = t.project_id LEFT JOIN users a0 ON a0.id = t.assignee_id JOIN users c ON c.id = t.created_by WHERE {$where} GROUP BY t.id"; }
function normalizeTask(array $task): array { $task['project_ids'] = $task['project_ids'] ? explode(',', $task['project_ids']) : ($task['project_id'] ? [$task['project_id']] : []); $task['assignee_ids'] = $task['assignee_ids'] ? explode(',', $task['assignee_ids']) : ($task['assignee_id'] ? [$task['assignee_id']] : []); $task['project_name'] = $task['project_names'] ?: $task['primary_project_name']; $task['assignee_name'] = $task['assignee_names'] ?: $task['primary_assignee_name']; return $task; }
function canAccessTask(PDO $pdo, array $user, string $userId, string $taskId): bool { [$sql, $params] = taskAccessSql($user, $userId); $query = $pdo->prepare("SELECT t.id FROM tasks t WHERE t.id = ? {$sql} LIMIT 1"); $query->execute(array_merge([$taskId], $params)); return (bool)$query->fetch(); }
function addHistory(PDO $pdo, string $taskId, string $userId, string $action, string $message): void { $pdo->prepare('INSERT INTO task_history (id, task_id, user_id, action, message) VALUES (?, ?, ?, ?, ?)')->execute([bin2hex(random_bytes(16)), $taskId, $userId, $action, $message]); }
function historyValue($value): string { $value = trim(preg_replace('/\s+/', ' ', strip_tags((string)$value))); if ($value === '') return 'не вказано'; return mb_strlen($value) > 160 ? mb_substr($value, 0, 160) . '…' : $value; }
function historyDescriptionChange(string $old, string $new): string { $oldText = historyValue($old); $newText = historyValue($new); preg_match_all('/<img\b/i', $old, $oldMatches); preg_match_all('/<img\b/i', $new, $newMatches); $oldImages = count($oldMatches[0]); $newImages = count($newMatches[0]); if ($oldText === $newText && $oldImages === $newImages) return ''; $images = $oldImages !== $newImages ? "; зображення: {$oldImages} → {$newImages}" : ''; return "опис: «{$oldText}» → «{$newText}»{$images}"; }

if ($method === 'GET') {
    [$accessSql, $accessParams] = taskAccessSql($user, $userId); $detailId = trim((string)($_GET['id'] ?? ''));
    if ($detailId !== '') {
        $query = $pdo->prepare(taskSelect("t.id = ? {$accessSql}")); $query->execute(array_merge([$detailId], $accessParams)); $task = $query->fetch(); if (!$task) jsonResponse(false, 'Задачу не знайдено або у вас немає доступу.', [], 404); $task = normalizeTask($task);
        $history = $pdo->prepare('SELECT h.id, h.user_id, h.action, h.message, h.created_at, u.name AS user_name FROM task_history h LEFT JOIN users u ON u.id = h.user_id WHERE h.task_id = ? ORDER BY h.created_at DESC'); $history->execute([$detailId]); $attachments = $pdo->prepare('SELECT id, file_name, file_url, mime_type, created_at FROM task_attachments WHERE task_id = ? ORDER BY created_at DESC'); $attachments->execute([$detailId]); $timeEntries = $pdo->prepare('SELECT te.id, te.user_id, te.minutes, te.note, te.logged_at, u.name AS user_name FROM time_entries te JOIN users u ON u.id = te.user_id WHERE te.task_id = ? ORDER BY te.logged_at DESC'); $timeEntries->execute([$detailId]); $timeRows = $timeEntries->fetchAll(); $totalMinutes = array_sum(array_map(static fn(array $row): int => (int)$row['minutes'], $timeRows));
        jsonResponse(true, 'Задачу завантажено.', ['user' => $user, 'task' => $task, 'history' => $history->fetchAll(), 'attachments' => $attachments->fetchAll(), 'time_entries' => $timeRows, 'total_minutes' => $totalMinutes]);
    }
    $query = $pdo->prepare(taskSelect("1=1 {$accessSql}") . ' ORDER BY t.due_date IS NULL, t.due_date, t.created_at DESC'); $query->execute($accessParams); $tasks = array_map('normalizeTask', $query->fetchAll());
    if ($isAdmin) { $projectQuery = $pdo->query('SELECT id, name FROM projects ORDER BY name'); $peopleQuery = $pdo->query('SELECT id, name, email FROM users ORDER BY name'); } else { $projectQuery = $pdo->prepare('SELECT DISTINCT p.id, p.name FROM projects p LEFT JOIN project_members pm ON pm.project_id = p.id WHERE p.owner_id = ? OR pm.user_id = ? ORDER BY p.name'); $projectQuery->execute([$userId, $userId]); $peopleQuery = $pdo->prepare("SELECT DISTINCT u.id, u.name, u.email FROM users u WHERE u.id = ? OR EXISTS (SELECT 1 FROM project_members pm JOIN projects p ON p.id = pm.project_id WHERE pm.user_id = u.id AND (p.owner_id = ? OR EXISTS (SELECT 1 FROM project_members pm2 WHERE pm2.project_id = p.id AND pm2.user_id = ?))) ORDER BY u.name"); $peopleQuery->execute([$userId, $userId, $userId]); }
    jsonResponse(true, 'Задачі завантажено.', ['user' => $user, 'tasks' => $tasks, 'projects' => $projectQuery->fetchAll(), 'people' => $peopleQuery->fetchAll(), 'permissions' => ['create' => true, 'admin' => $isAdmin]]);
}
if ($method !== 'POST') jsonResponse(false, 'Метод не підтримується.', [], 405);
if ($action === 'add_history') { $taskId = trim((string)($data['id'] ?? '')); $message = trim((string)($data['message'] ?? '')); if (!$taskId || !$message) jsonResponse(false, 'Дані історії неповні.', [], 422); if (!canAccessTask($pdo, $user, $userId, $taskId)) jsonResponse(false, 'Немає доступу до задачі.', [], 403); addHistory($pdo, $taskId, $userId, 'description_detail', $message); jsonResponse(true, 'Дію додано в історію.'); }
if ($action === 'set_reminder') { $taskId = trim((string)($data['task_id'] ?? '')); $reminderAt = trim((string)($data['reminder_at'] ?? '')) ?: null; if (!$taskId || !canAccessTask($pdo, $user, $userId, $taskId)) jsonResponse(false, 'Немає доступу до задачі.', [], 403); if ($reminderAt !== null) { $date = DateTime::createFromFormat('Y-m-d\TH:i', $reminderAt); if (!$date || $date->format('Y-m-d\TH:i') !== $reminderAt) jsonResponse(false, 'Вкажіть коректну дату та час.', [], 422); } $pdo->prepare('UPDATE tasks SET reminder_at = ? WHERE id = ?')->execute([$reminderAt, $taskId]); if ($reminderAt) addHistory($pdo, $taskId, $userId, 'reminder_updated', 'Нагадування перенесено на ' . $date->format('d.m.Y H:i') . '.'); else addHistory($pdo, $taskId, $userId, 'reminder_removed', 'Нагадування вимкнено.'); jsonResponse(true, $reminderAt ? 'Нове нагадування встановлено.' : 'Нагадування вимкнено.'); }
if ($action === 'log_time') { $taskId = trim((string)($data['task_id'] ?? '')); $minutes = (int)($data['minutes'] ?? 0); $note = trim((string)($data['note'] ?? '')) ?: null; if (!$taskId || $minutes < 1 || $minutes > 1440) jsonResponse(false, 'Вкажіть час від 1 до 1440 хвилин.', [], 422); if (!canAccessTask($pdo, $user, $userId, $taskId)) jsonResponse(false, 'Немає доступу до задачі.', [], 403); $pdo->prepare('INSERT INTO time_entries (id, task_id, user_id, minutes, note) VALUES (?, ?, ?, ?, ?)')->execute([bin2hex(random_bytes(16)), $taskId, $userId, $minutes, $note]); $hours = intdiv($minutes, 60); $rest = $minutes % 60; $timeLabel = $hours ? "{$hours} год " . ($rest ? "{$rest} хв" : '') : "{$rest} хв"; addHistory($pdo, $taskId, $userId, 'time_logged', "Додано {$timeLabel} роботи" . ($note ? " ({$note})" : '') . '.'); jsonResponse(true, 'Час додано до задачі.'); }
if ($action === 'add_attachment') { $taskId = trim((string)($data['task_id'] ?? '')); $url = trim((string)($data['file_url'] ?? '')); $fileName = trim((string)($data['file_name'] ?? 'Зображення')); if (!$taskId || !$url || !filter_var($url, FILTER_VALIDATE_URL)) jsonResponse(false, 'Вкажіть коректне посилання на зображення.', [], 422); if (!canAccessTask($pdo, $user, $userId, $taskId)) jsonResponse(false, 'Немає доступу до задачі.', [], 403); $pdo->prepare('INSERT INTO task_attachments (id, task_id, user_id, file_name, file_url, mime_type) VALUES (?, ?, ?, ?, ?, ?)')->execute([bin2hex(random_bytes(16)), $taskId, $userId, $fileName, $url, 'image/*']); addHistory($pdo, $taskId, $userId, 'attachment_added', "Додано зображення «{$fileName}»."); jsonResponse(true, 'Зображення додано.'); }
if ($action === 'create' || $action === 'update') {
    $title = trim((string)($data['title'] ?? '')); if ($title === '') jsonResponse(false, 'Введіть назву задачі.', [], 422); $statuses = ['todo', 'in_progress', 'done', 'cancelled']; $priorities = ['low', 'normal', 'high', 'urgent']; $status = in_array($data['status'] ?? 'todo', $statuses, true) ? $data['status'] : 'todo'; $priority = in_array($data['priority'] ?? 'normal', $priorities, true) ? $data['priority'] : 'normal'; $projectIds = idList($data['project_ids'] ?? ($data['project_id'] ?? [])); $assigneeIds = idList($data['assignee_ids'] ?? ($data['assignee_id'] ?? [])); $dueDate = trim((string)($data['due_date'] ?? '')) ?: null; $reminderAt = trim((string)($data['reminder_at'] ?? '')) ?: null; $creatorReminder = $canManage && !empty($data['creator_reminder']) ? 1 : 0; $description = trim((string)($data['description'] ?? '')); $clientName = trim((string)($data['client_name'] ?? '')) ?: null;
    if (($data['status'] ?? '') === 'archived') $status = 'archived';
    $projectCheck = $pdo->prepare('SELECT p.id FROM projects p LEFT JOIN project_members pm ON pm.project_id = p.id AND pm.user_id = ? WHERE p.id = ? AND (p.owner_id = ? OR pm.user_id IS NOT NULL OR ? IN (SELECT id FROM users WHERE role IN (\'admin\', \'owner\'))) LIMIT 1'); foreach ($projectIds as $projectId) { $projectCheck->execute([$userId, $projectId, $userId, $userId]); if (!$projectCheck->fetch()) jsonResponse(false, 'У вас немає доступу до одного з вибраних проєктів.', [], 403); }
    if ($assigneeIds) { $marks = implode(',', array_fill(0, count($assigneeIds), '?')); $peopleCheck = $pdo->prepare("SELECT COUNT(*) FROM users WHERE id IN ({$marks})"); $peopleCheck->execute($assigneeIds); if ((int)$peopleCheck->fetchColumn() !== count($assigneeIds)) jsonResponse(false, 'Одного з виконавців не знайдено.', [], 422); }
    $primaryProject = $projectIds[0] ?? null; $primaryAssignee = $assigneeIds[0] ?? null; $oldAssigneeIds = [];
    if ($action === 'create') { $taskId = bin2hex(random_bytes(16)); $pdo->prepare('INSERT INTO tasks (id, title, description, client_name, project_id, assignee_id, created_by, status, priority, due_date, reminder_at, creator_reminder) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)')->execute([$taskId, $title, $description, $clientName, $primaryProject, $primaryAssignee, $userId, $status, $priority, $dueDate, $reminderAt, $creatorReminder]); addHistory($pdo, $taskId, $userId, 'created', 'Задачу створено.'); }
    else { $taskId = trim((string)($data['id'] ?? '')); if (!$taskId || !canAccessTask($pdo, $user, $userId, $taskId)) jsonResponse(false, 'Немає доступу до цієї задачі.', [], 403); $old = $pdo->prepare('SELECT title, description, client_name, status, priority, due_date, reminder_at, creator_reminder FROM tasks WHERE id = ?'); $old->execute([$taskId]); $oldTask = $old->fetch(); $oldAssignments = $pdo->prepare('SELECT user_id FROM task_assignees WHERE task_id = ?'); $oldAssignments->execute([$taskId]); $oldAssigneeIds = array_column($oldAssignments->fetchAll(), 'user_id'); $oldProjects = $pdo->prepare('SELECT project_id FROM task_projects WHERE task_id = ?'); $oldProjects->execute([$taskId]); $oldProjectIds = array_column($oldProjects->fetchAll(), 'project_id'); $pdo->prepare('UPDATE tasks SET title = ?, description = ?, client_name = ?, project_id = ?, assignee_id = ?, status = ?, priority = ?, due_date = ?, reminder_at = ?, creator_reminder = ? WHERE id = ?')->execute([$title, $description, $clientName, $primaryProject, $primaryAssignee, $status, $priority, $dueDate, $reminderAt, $creatorReminder, $taskId]); $pdo->prepare('DELETE FROM task_projects WHERE task_id = ?')->execute([$taskId]); $pdo->prepare('DELETE FROM task_assignees WHERE task_id = ?')->execute([$taskId]); $changes = []; foreach (['title' => 'назва задачі', 'client_name' => 'клієнт', 'status' => 'статус', 'priority' => 'пріоритет', 'due_date' => 'дедлайн', 'reminder_at' => 'нагадування'] as $field => $label) { $newValue = $field === 'client_name' ? $clientName : ($field === 'status' ? $status : ($field === 'priority' ? $priority : ($field === 'due_date' ? $dueDate : ($field === 'reminder_at' ? $reminderAt : $title)))); if ((string)($oldTask[$field] ?? '') !== (string)($newValue ?? '')) $changes[] = "{$label}: «" . historyValue($oldTask[$field] ?? null) . "» → «" . historyValue($newValue) . "»"; } if ((int)($oldTask['creator_reminder'] ?? 0) !== $creatorReminder) $changes[] = 'видимість нагадування: «' . ((int)($oldTask['creator_reminder'] ?? 0) ? 'увімкнено' : 'вимкнено') . '» → «' . ($creatorReminder ? 'увімкнено' : 'вимкнено') . '»'; $descriptionChange = historyDescriptionChange((string)($oldTask['description'] ?? ''), $description); if ($descriptionChange !== '') $changes[] = $descriptionChange; if (array_diff($projectIds, $oldProjectIds) || array_diff($oldProjectIds, $projectIds)) $changes[] = 'змінено проєкти'; if (array_diff($assigneeIds, $oldAssigneeIds) || array_diff($oldAssigneeIds, $assigneeIds)) $changes[] = 'змінено виконавців'; if ($changes) addHistory($pdo, $taskId, $userId, 'updated', implode('; ', $changes) . '.'); }
    $projectInsert = $pdo->prepare('INSERT IGNORE INTO task_projects (task_id, project_id) VALUES (?, ?)'); foreach ($projectIds as $projectId) $projectInsert->execute([$taskId, $projectId]); $assigneeInsert = $pdo->prepare('INSERT IGNORE INTO task_assignees (task_id, user_id) VALUES (?, ?)'); foreach ($assigneeIds as $assigneeId) $assigneeInsert->execute([$taskId, $assigneeId]);
    $notificationInsert = $pdo->prepare("INSERT INTO notifications (id, user_id, sender_id, type, title, message, entity_type, entity_id) VALUES (?, ?, ?, 'task_assigned', ?, ?, 'task', ?)"); foreach ($assigneeIds as $assigneeId) if ($assigneeId !== $userId && !in_array($assigneeId, $oldAssigneeIds, true)) { $notificationInsert->execute([bin2hex(random_bytes(16)), $assigneeId, $userId, 'Вам призначили задачу', "Вам призначили задачу «{$title}».", $taskId]); if ($action === 'update') addHistory($pdo, $taskId, $userId, 'assignee_added', 'Додано нового виконавця до задачі.'); }
    jsonResponse(true, $action === 'create' ? 'Задачу створено.' : 'Задачу оновлено.', ['task_id' => $taskId]);
}
if ($action === 'archive') { $taskId = trim((string)($data['id'] ?? '')); if (!$taskId) jsonResponse(false, 'Задачу не вказано.', [], 422); if ($isAdmin) { $query = $pdo->prepare("UPDATE tasks SET status = 'archived' WHERE id = ?"); $query->execute([$taskId]); } else { $query = $pdo->prepare("UPDATE tasks SET status = 'archived' WHERE id = ? AND created_by = ?"); $query->execute([$taskId, $userId]); } if ($query->rowCount() === 0) jsonResponse(false, 'Ви можете архівувати лише власні задачі.', [], 403); addHistory($pdo, $taskId, $userId, 'archived', 'Задачу переміщено до архіву.'); jsonResponse(true, 'Задачу переміщено до архіву.'); }
if ($action === 'delete') { $taskId = trim((string)($data['id'] ?? '')); if (!$taskId) jsonResponse(false, 'Задачу не вказано.', [], 422); if ($isAdmin) { $query = $pdo->prepare('DELETE FROM tasks WHERE id = ?'); $query->execute([$taskId]); } else { $query = $pdo->prepare('DELETE FROM tasks WHERE id = ? AND created_by = ?'); $query->execute([$taskId, $userId]); } if ($query->rowCount() === 0) jsonResponse(false, 'Ви можете видаляти лише власні задачі.', [], 403); jsonResponse(true, 'Задачу видалено.'); }
jsonResponse(false, 'Невідома дія.', [], 422);
